import{_ as e,c as r,o,a as s}from"./app.19f3f8f0.js";const g=JSON.parse('{"title":"Episode 3 — Keywords & once per person","description":"Cut spam and duplicate DMs with keyword rules and a once-per-user option.","frontmatter":{"title":"Episode 3 — Keywords & once per person","description":"Cut spam and duplicate DMs with keyword rules and a once-per-user option."},"headers":[{"level":2,"title":"Keywords","slug":"keywords","link":"#keywords","children":[]},{"level":2,"title":"Once per person","slug":"once-per-person","link":"#once-per-person","children":[]},{"level":2,"title":"Try this on your next launch","slug":"try-this-on-your-next-launch","link":"#try-this-on-your-next-launch","children":[]},{"level":2,"title":"Series","slug":"series","link":"#series","children":[]}],"relativePath":"replybridge/series/03-keywords-once.md"}'),n={name:"replybridge/series/03-keywords-once.md"},t=s('<h1 id="episode-3-—-keywords-once-per-person" tabindex="-1">Episode 3 — Keywords &amp; “once per person” <a class="header-anchor" href="#episode-3-—-keywords-once-per-person" aria-hidden="true">#</a></h1><p>Two features keep automation <strong>clean</strong>:</p><h2 id="keywords" tabindex="-1">Keywords <a class="header-anchor" href="#keywords" aria-hidden="true">#</a></h2><p>Only send your DM when the comment includes words you care about—e.g. <strong>INFO</strong>, <strong>PRICE</strong>, <strong>LINK</strong>.</p><p><strong>Why it helps:</strong> Random emoji-only comments or spam don’t trigger your message.</p><h2 id="once-per-person" tabindex="-1">Once per person <a class="header-anchor" href="#once-per-person" aria-hidden="true">#</a></h2><p>On a single post, each user gets your DM <strong>only once</strong> (when you turn this on).</p><p><strong>Why it helps:</strong> Great for <strong>giveaways</strong>, <strong>lead magnets</strong>, or events where you don’t want the same person spamming comments for multiple DMs.</p><hr><h2 id="try-this-on-your-next-launch" tabindex="-1">Try this on your next launch <a class="header-anchor" href="#try-this-on-your-next-launch" aria-hidden="true">#</a></h2><ol><li>Pick <strong>one keyword</strong> you say in the caption (easy to copy).</li><li>Turn on <strong>once per person</strong> if it’s a promo or contest.</li><li>Watch your stats in the app to see how many people matched.</li></ol><p>More detail: <strong><a href="/replybridge/usage">How to use</a></strong></p><hr><h2 id="series" tabindex="-1">Series <a class="header-anchor" href="#series" aria-hidden="true">#</a></h2><ul><li><strong>Previous:</strong> <a href="/replybridge/series/02-dm-or-public-reply">Episode 2</a></li><li><strong>Next:</strong> <a href="/replybridge/series/04-automation-end-date">Episode 4 — Automation end date</a></li><li><strong>All episodes:</strong> <a href="/replybridge/series/">Instagram mini-series</a></li></ul>',15),a=[t];function i(d,p,l,h,c,u){return o(),r("div",null,a)}const m=e(n,[["render",i]]);export{g as __pageData,m as default};
